import { useState } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { toast } from 'sonner'
import { UserPlus, X } from 'lucide-react'
import { useTenant } from '@/app/providers/TenantProvider'
import { membersService, type Member } from '@/integrations/supabase/members'

export function MembersPage() {
  const { manifest } = useTenant()
  const tenantId = manifest?.tenantId ?? ''
  const qc = useQueryClient()
  const [showInvite, setShowInvite] = useState(false)
  const [email, setEmail] = useState('')
  const [role, setRole] = useState<Member['role']>('member')

  const { data: members = [], isLoading } = useQuery({
    queryKey: ['members', tenantId],
    queryFn: () => membersService.listMembers(tenantId),
    enabled: !!tenantId,
  })

  const inviteMut = useMutation({
    mutationFn: () => membersService.inviteMember(tenantId, email, role),
    onSuccess: () => {
      toast.success('Invitation sent')
      qc.invalidateQueries({ queryKey: ['members', tenantId] })
      setShowInvite(false)
      setEmail('')
    },
    onError: (e: Error) => toast.error(e.message),
  })

  return (
    <div className="h-full overflow-y-auto p-6">
      <div className="max-w-3xl mx-auto">
        <div className="flex items-center justify-between mb-6">
          <h2 className="font-semibold">Members</h2>
          <button onClick={() => setShowInvite(true)} className="flex items-center gap-1.5 text-sm bg-accent text-accent-foreground px-3 py-1.5 rounded-lg hover:opacity-90">
            <UserPlus size={14} /> Invite member
          </button>
        </div>
        {isLoading ? (
          <p className="text-sm text-muted-foreground">Loading…</p>
        ) : members.length === 0 ? (
          <div className="rounded-xl border border-dashed border-border p-10 text-center">
            <p className="text-sm text-muted-foreground">No members yet</p>
          </div>
        ) : (
          <div className="bg-surface rounded-xl border border-border overflow-hidden">
            <table className="w-full text-sm">
              <thead className="border-b border-border">
                <tr>{['Name', 'Email', 'Role', 'Status', 'Actions'].map((h) => <th key={h} className="text-left px-4 py-3 text-xs text-muted-foreground font-medium">{h}</th>)}</tr>
              </thead>
              <tbody>
                {members.map((m) => (
                  <tr key={m.id} className="border-b border-border last:border-0 hover:bg-muted/50">
                    <td className="px-4 py-3 font-medium">{m.name}</td>
                    <td className="px-4 py-3 text-muted-foreground">{m.email}</td>
                    <td className="px-4 py-3 capitalize">{m.role}</td>
                    <td className="px-4 py-3">
                      <span className={`px-2 py-0.5 rounded-full text-xs ${m.status === 'active' ? 'bg-success/10 text-success' : 'bg-warning/10 text-warning'}`}>{m.status}</span>
                    </td>
                    <td className="px-4 py-3"><button className="text-xs text-accent hover:underline">Edit</button></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {showInvite && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-surface rounded-2xl border border-border w-full max-w-md shadow-xl">
            <div className="flex items-center justify-between p-5 border-b border-border">
              <h3 className="font-semibold">Invite member</h3>
              <button onClick={() => setShowInvite(false)} className="p-1.5 rounded-lg hover:bg-muted"><X size={16} /></button>
            </div>
            <div className="p-5 flex flex-col gap-4">
              <div>
                <label className="text-sm font-medium block mb-1.5">Email</label>
                <input value={email} onChange={(e) => setEmail(e.target.value)} type="email" autoFocus className="w-full rounded-lg border border-border bg-background px-3 py-2 text-sm outline-none focus:border-accent" />
              </div>
              <div>
                <label className="text-sm font-medium block mb-1.5">Role</label>
                <select value={role} onChange={(e) => setRole(e.target.value as Member['role'])} className="w-full rounded-lg border border-border bg-background px-3 py-2 text-sm outline-none focus:border-accent">
                  <option value="viewer">Viewer</option>
                  <option value="member">Member</option>
                  <option value="admin">Admin</option>
                  <option value="owner">Owner</option>
                </select>
              </div>
              <div className="flex justify-end gap-2">
                <button onClick={() => setShowInvite(false)} className="px-4 py-2 text-sm text-muted-foreground hover:text-foreground">Cancel</button>
                <button onClick={() => inviteMut.mutate()} disabled={!email || inviteMut.isPending} className="px-4 py-2 text-sm bg-accent text-accent-foreground rounded-lg hover:opacity-90 disabled:opacity-50">
                  {inviteMut.isPending ? 'Inviting…' : 'Send invite'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}
